import{z as B,x as A,o as n,c as p,q as s,j as r,D as t,d as e,s as i,S as l,b as E}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"可行能力方法","description":"","frontmatter":{"title":"可行能力方法","date":"2026-09-27T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/capability-approach.md","filePath":"econ/capability-approach.md","lastUpdated":1791413859000}'),d={name:"econ/capability-approach.md"};function D(m,a,c,u,g,h){const o=A("Mermaid");return n(),p("div",null,[a[2]||(a[2]=s('<h1 id="可行能力方法" tabindex="-1">可行能力方法 <a class="header-anchor" href="#可行能力方法" aria-label="Permalink to &quot;可行能力方法&quot;">​</a></h1><div class="epigraph"><p>问「有多少钱」不如问「能做成什么事」：发展是把人能过的真实生活集合撑大，收入只是撑大它的手段之一。</p><footer>—— 据 Sen《Commodities and Capabilities》(1985)；《Development as Freedom》(1999)；Nussbaum 能力清单</footer></div><p><a href="/econ/gini-decomposition">Gini 系数分解</a>把收入不平等拆细，本课挑战的是「收入」这个测量原点本身。缺口是<strong>可行能力方法</strong>：福祉的度量对象应是人可实现的「功能」（doings and beings）集合，而非商品束。它改写了人类发展指数与多维贫困指数的地基。本课不进 Nussbaum 的哲学清单之争。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>两个人收入相同：一位健康、有学上、说话有人听；一位慢性病、失学、无处发声。收入维度上平等，生活上天壤之别。缺口：<strong>转化的异质性</strong>——同样的商品投入，因身体、社会规范、公共品差异，转化成的生活质量不同。福利经济学以效用为终点、以收入为代理，两者都会漏掉这层转化。</p><p><span class="marginnote">术语翻译：功能（functioning）= 已实现的生活状态，如「营养良好」「能读写」；能力（capability）= 可实现的功能集合，即「真实机会」——吃素不是能力受限，吃不起肉才是。福祉按能力评估，按功能实现与否落笔。</span></p><p><span class="marginnote">数字实例：同样月入 3000 元，孕妇对营养与医疗的转化需求更高；轮椅使用者在无坡道城市里「 mobility 」这一功能实际为零——收入相同，能力悬殊。HDI 用「人均 GNI + 教育 + 寿命」三轴逼近能力，MPI 直接数剥夺维度。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>操作化两路。<strong>指数路</strong>：UNDP 的 HDI（寿命/教育/收入几何平均）与 OPHI 的 MPI（10 个二值剥夺指标、按维度计数识别贫困者）——把「能力集合」压缩成可跨年跨国的标量。<strong>评估路</strong>：政策评估时对每个候选维度回答三问——这算一种重要的功能吗、缺失是选择还是约束、干预能否拓宽集合。方法上承认不完备：Sen 拒绝给唯一清单，留出公共理性审议空间。</p>',9)),(n(),r(l,null,{default:t(()=>[i(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%95%86%E5%93%81%2F%E6%94%B6%E5%85%A5%20x%22%5D%20--%3E%20B%5B%22%E8%BD%AC%E5%8C%96%E5%9B%A0%E7%B4%A0%3A%20%E8%BA%AB%E4%BD%93%2F%E7%A4%BE%E4%BC%9A%2F%E7%8E%AF%E5%A2%83%22%5D%0A%20%20B%20--%3E%20C%5B%22%E5%8A%9F%E8%83%BD%E5%90%91%E9%87%8F%20b(x)%22%5D%0A%20%20C%20--%3E%20D%5B%22%E8%83%BD%E5%8A%9B%E9%9B%86%20%3D%20%E5%8F%AF%E9%80%89%E5%8A%9F%E8%83%BD%E9%9B%86%E5%90%88%22%5D%0A%20%20D%20--%3E%20E%7B%22%E5%BA%A6%E9%87%8F%E8%B7%AF%3F%22%7D%0A%20%20E%20--%3E%7C%22%E5%8E%8B%E7%BC%A9%E6%88%90%E6%8C%87%E6%95%B0%22%7C%20F%5B%22HDI%20%2F%20MPI%22%5D%0A%20%20E%20--%3E%7C%22%E9%80%90%E6%A1%88%E5%AE%A1%E8%AE%AE%22%7C%20G%5B%22%E6%94%BF%E7%AD%96%E8%AF%84%E4%BC%B0%E4%B8%89%E9%97%AE%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,[E("span",{class:"marginnote"},"直觉类比：收入像食材预算，功能像做出来的菜，能力像「这套厨房里你能做的所有菜」——同样的预算，有人厨房有灶、有人只有微波炉；发展政策的目标不是只发食材，是把厨房（教育、健康、基础设施、权利）改造好。")],-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,[e("能力法改写福利经济学的三处地基。"),E("strong",null,"评估对象"),e("：从效用（心理满足，可被适应扭曲）移到能力集合（客观机会）——「贫者安贫」不再自动等于福祉；"),E("strong",null,"平等目标"),e("：从收入平等或效用平等移到能力平等——女性教育回报、残疾人无障碍都是其自然推论；"),E("strong",null,"发展定义"),e("：增长是手段，能力扩张是目的，GDP 之外需自建仪表盘。机制上它承认度量损失换来解释力：单一指数必然武断，但方向正确的粗测量胜过精确的错误测量。")],-1)),(n(),r(l,null,{default:t(()=>[i(o,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%7B%22%E8%83%BD%E5%8A%9B%E6%B3%95%E6%94%B9%E4%BA%86%E4%BB%80%E4%B9%88%3F%22%7D%20--%3E%20R%5B%22%E7%BB%88%E7%82%B9%3A%20%E6%95%88%E7%94%A8%20%E2%86%92%20%E8%83%BD%E5%8A%9B%E9%9B%86%E5%90%88%22%5D%0A%20%20Q%20--%3E%20S%5B%22%E5%B9%B3%E7%AD%89%3A%20%E6%94%B6%E5%85%A5%20%E2%86%92%20%E8%83%BD%E5%8A%9B%22%5D%0A%20%20Q%20--%3E%20T%5B%22%E5%8F%91%E5%B1%95%3A%20%E5%A2%9E%E9%95%BF%20%E2%86%92%20%E8%87%AA%E7%94%B1%E6%89%A9%E5%BC%A0%22%5D%0A%20%20U%7B%22%E9%80%82%E5%BA%94%E6%80%A7%E9%97%AE%E9%A2%98%22%7D%20--%3E%20V%5B%22%E4%B8%BB%E8%A7%82%E6%95%88%E7%94%A8%E8%A2%AB%E5%8E%8B%E4%BD%8E%22%5D%0A%20%20V%20--%3E%20W%5B%22%E5%AE%A2%E8%A7%82%E8%83%BD%E5%8A%9B%E7%BB%B4%E5%BA%A6%E5%85%9C%E5%BA%95%22%5D%0A%20%20T%20--%3E%20W%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=s('<p><span class="marginnote">常见误区：把能力法读成「反增长」——Sen 明确增长是能力扩张的重要引擎，反对的是把增长当唯一目标；另一误区是「清单一定要全」——MPI 的 10 个指标远非完备，它是诊断起点不是人生清单。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>三大批评与回应：<strong>文化帝国主义</strong>（清单谁来定？）——回应是公共理性过程而非哲学独断；<strong>度量武断</strong>（维度权重怎么定？）——MPI 用等权起步再 robustness 检验；<strong>信息要求高</strong>（细化到个人能力需大量调查）——面板与人口普查部分弥补。适用性：发展中世界扶贫与人类发展报告是主场，发达社会的适用需换维度（时间贫困、数字接入）。与收入度量的分工不是替代：收入回答「手段分配」，能力回答「生活结果」，政策审计两者都要。</p><p><span class="marginnote">直觉类比：收入基尼像只看油箱油量，能力法是看整辆车——轮胎、引擎、路权；有人油满而车开不动（残疾人在城市里），有人油少但路平车好（北欧福利国家），单看油箱会误诊。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>福祉的度量对象是能力集合（真实机会），收入只是转化输入之一。</li><li>HDI/MPI 是其操作化；转化异质性是收入法漏掉的核。</li><li>承认度量武断，用公共理性与 robustness 换方向正确。</li><li>出处：Sen《Commodities and Capabilities》1985；《Development as Freedom》1999；Alkire–Foster 2011；UNDP HDI 技术注。</li></ul>',6))])}const C=B(d,[["render",D]]);export{f as __pageData,C as default};
